import { Router } from 'express';
import db from '../db/index.js';
import {
  NYUAD_CAMPUS,
  OTHER_SERVICES,
  REAL_STOPS,
  ROUTES,
  SCHEDULE_INFO,
  routeWaypoints,
} from '../data/shuttleSchedule.js';
// Road-following paths, generated by scripts/build-shuttle-paths.mjs.
import ROAD_PATHS from '../data/shuttlePaths.json' with { type: 'json' };


// The road path if it was generated from this route's current stops, else straight lines between
// them (e.g. a stop moved and nobody re-ran the script). [] when the route has no mapped stops.
function mapPath(route) {
  const waypoints = routeWaypoints(route);
  if (waypoints.length < 3) return { path: [], follows_roads: false };
  const road = ROAD_PATHS[route.key];
  if (road && JSON.stringify(road.waypoints) === JSON.stringify(waypoints)) {
    return { path: road.path, follows_roads: true };
  }
  return { path: waypoints, follows_roads: false };
}

const router = Router();

// Today's date in Abu Dhabi as YYYY-MM-DD (en-CA formats dates that way).
function abuDhabiToday() {
  return new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Dubai' }).format(new Date());
}

// Routes + timetable come from data/shuttleSchedule.js; stop ids come from the DB so the client
// can match a restaurant's nearest_shuttle_stop.id to the routes that serve it.
router.get('/', async (_req, res) => {
  const stops = await db.all('SELECT id, name, lat, lng FROM shuttle_stops');
  const stopByKey = {};
  for (const real of REAL_STOPS) {
    const row = stops.find((s) => s.name === real.name);
    if (row) stopByKey[real.key] = row;
  }

  const today = abuDhabiToday();
  const routes = ROUTES.filter(
    (r) => (!r.validFrom || today >= r.validFrom) && (!r.validUntil || today <= r.validUntil)
  ).map((r) => {
    const routeStops = r.stops.map(({ label, stop }) => {
      if (stop === 'campus') return { label, stop_id: null, is_campus: true, ...NYUAD_CAMPUS };
      const row = stop ? stopByKey[stop] : null;
      return { label, stop_id: row?.id ?? null, is_campus: false, lat: row?.lat ?? null, lng: row?.lng ?? null };
    });
    return {
      key: r.key,
      name: r.name,
      color: r.color,
      service: r.service,
      stops: routeStops,
      trips: r.trips,
      ...mapPath(r),
    };
  });

  res.json({
    info: SCHEDULE_INFO,
    campus: { label: 'Saadiyat Campus', ...NYUAD_CAMPUS },
    stops,
    routes,
    other_services: OTHER_SERVICES,
  });
});

export default router;
